import math

def simulate(doc, scope, inputs, params, start=None, horizon=None):
    rec_end = recorded_end(doc, scope)
    if horizon is None:
        horizon = rec_end if rec_end is not None else 127.0
    if start is None:
        start = 0.0

    objects = {}
    pending = []
    for inp in sorted(inputs, key=lambda x: x['time']):
        t_in = inp['time']
        oid = inp['entities'][0]
        fields = inp['fields']
        if t_in <= start:
            dt = start - t_in
            objects[oid] = {
                'x': fields['x'] + fields['vx'] * dt * 0.028,
                'y': fields['y'] + fields['vy'] * dt * 0.028,
                'vx': fields['vx'],
                'vy': fields['vy'],
                'exited': False
            }
        else:
            pending.append((t_in, inp))

    outcomes = []
    collided = set()
    t = start
    step = 1.0
    pos_scale = 0.028
    coll_dist = 0.46
    exit_bound = 4.5

    while t <= horizon:
        curr_step = min(step, horizon - t + 1e-9)
        if curr_step < 1e-6:
            break

        while pending and pending[0][0] <= t + curr_step:
            _, inp = pending.pop(0)
            oid = inp['entities'][0]
            objects[oid] = {
                'x': inp['fields']['x'], 'y': inp['fields']['y'],
                'vx': inp['fields']['vx'], 'vy': inp['fields']['vy'],
                'exited': False
            }

        for oid, obj in objects.items():
            if not obj['exited']:
                obj['x'] += obj['vx'] * pos_scale * curr_step
                obj['y'] += obj['vy'] * pos_scale * curr_step

                if abs(obj['x']) > exit_bound or abs(obj['y']) > exit_bound:
                    obj['exited'] = True
                    outcomes.append({
                        'time': float(round(t)),
                        'kind': 'exit',
                        'entities': [oid],
                        'value': None,
                        'src': []
                    })

        oids = list(objects.keys())
        for i in range(len(oids)):
            for j in range(i + 1, len(oids)):
                o1, o2 = oids[i], oids[j]
                if objects[o1]['exited'] or objects[o2]['exited']:
                    continue
                if (o1, o2) in collided:
                    continue

                dx = objects[o1]['x'] - objects[o2]['x']
                dy = objects[o1]['y'] - objects[o2]['y']
                d = math.hypot(dx, dy)

                if d < coll_dist and d > 1e-6:
                    collided.add((o1, o2))
                    outcomes.append({
                        'time': float(round(t)),
                        'kind': 'collision',
                        'entities': [o1, o2],
                        'value': None,
                        'src': []
                    })

                    nx, ny = dx / d, dy / d
                    dvx = objects[o1]['vx'] - objects[o2]['vx']
                    dvy = objects[o1]['vy'] - objects[o2]['vy']
                    dot = dvx * nx + dvy * ny
                    objects[o1]['vx'] -= dot * nx
                    objects[o1]['vy'] -= dot * ny
                    objects[o2]['vx'] += dot * nx
                    objects[o2]['vy'] += dot * ny

                    overlap = coll_dist - d
                    objects[o1]['x'] -= nx * overlap * 0.5
                    objects[o1]['y'] -= ny * overlap * 0.5
                    objects[o2]['x'] += nx * overlap * 0.5
                    objects[o2]['y'] += ny * overlap * 0.5

        t += curr_step

    return outcomes

