import math

def simulate(doc, scope, inputs, params, start=None, horizon=None):
    rec_end = recorded_end(doc, scope)
    if horizon is None:
        horizon = rec_end if rec_end is not None else 128.0
    if start is None:
        start = 0.0

    inputs_sorted = sorted(inputs, key=lambda x: float(x['time']))

    state = {}
    obj_latest = {}
    for inp in inputs_sorted:
        oid = inp['entities'][0]
        t = float(inp['time'])
        if t <= start:
            obj_latest[oid] = inp

    for oid, inp in obj_latest.items():
        state[oid] = {
            'x': float(inp['fields'].get('x', 0.0)),
            'y': float(inp['fields'].get('y', 0.0)),
            'vx': float(inp['fields'].get('vx', 0.0)),
            'vy': float(inp['fields'].get('vy', 0.0)),
            'active': True
        }

    future_entries = {}
    for inp in inputs_sorted:
        oid = inp['entities'][0]
        t = float(inp['time'])
        if t > start:
            future_entries[oid] = inp

    outcomes = []
    curr_time = start
    dt = 0.2
    epsilon = 0.75
    collision_thresh = 0.4
    exit_thresh = 4.5

    while curr_time <= horizon:
        for oid, inp in list(future_entries.items()):
            if float(inp['time']) <= curr_time:
                state[oid] = {
                    'x': float(inp['fields'].get('x', 0.0)),
                    'y': float(inp['fields'].get('y', 0.0)),
                    'vx': float(inp['fields'].get('vx', 0.0)),
                    'vy': float(inp['fields'].get('vy', 0.0)),
                    'active': True
                }
                del future_entries[oid]

        active_objs = {oid: s for oid, s in state.items() if s.get('active', False)}

        for oid, s in active_objs.items():
            speed = math.hypot(s['vx'], s['vy'])
            if speed > 0.01:
                s['vx'] *= 0.99 ** dt
                s['vy'] *= 0.99 ** dt
            else:
                s['vx'] = 0.0
                s['vy'] = 0.0
            s['x'] += s['vx'] * dt
            s['y'] += s['vy'] * dt

        collided = False
        ids = list(active_objs.keys())
        for i in range(len(ids)):
            if collided: break
            o1 = ids[i]
            s1 = active_objs[o1]
            for j in range(i + 1, len(ids)):
                if collided: break
                o2 = ids[j]
                s2 = active_objs[o2]

                dx = s2['x'] - s1['x']
                dy = s2['y'] - s1['y']
                dist = math.hypot(dx, dy)

                if dist < collision_thresh:
                    nx = dx / dist if dist > 1e-5 else 0
                    ny = dy / dist if dist > 1e-5 else 0

                    v_rel_x = s1['vx'] - s2['vx']
                    v_rel_y = s1['vy'] - s2['vy']
                    u = v_rel_x * nx + v_rel_y * ny

                    if u < 0:
                        impulse = (1 + epsilon) * u / 2
                        s1['vx'] -= impulse * nx
                        s1['vy'] -= impulse * ny
                        s2['vx'] += impulse * nx
                        s2['vy'] += impulse * ny

                    outcomes.append({
                        'time': round(curr_time, 1),
                        'kind': 'collision',
                        'entities': [o1, o2],
                        'value': None,
                        'src': []
                    })
                    collided = True
                    break

        for oid, s in list(active_objs.items()):
            if not s.get('active', False): continue
            if abs(s['x']) > exit_thresh or abs(s['y']) > exit_thresh:
                s['active'] = False
                outcomes.append({
                    'time': round(curr_time, 1),
                    'kind': 'exit',
                    'entities': [oid],
                    'value': None,
                    'src': []
                })

        curr_time += dt

    return outcomes

