            'frame': float(row['frame']), 'x': float(row['x']), 'y': float(row['y']),
            'vx': float(row['vx']), 'vy': float(row['vy'])
        })
    for oid in obj_data: obj_data[oid].sort(key=lambda r: r['frame'])
    return obj_data

