import math
import re
from collections import defaultdict

def simulate(doc, scope, inputs, params, start=None, horizon=None):
    rec_end = recorded_end(doc, scope)
    if horizon is None:
        horizon = rec_end if rec_end is not None else 128.0
    if start is None:
        start = 0.0

    scale = 1.0 / 36.0
    friction_rate = 0.99
    collision_thresh = 0.42
    exit_x_min, exit_x_max = -6.0, 6.0
    exit_y_min, exit_y_max = -5.0, 5.0

    scope_node = node_by_title(doc, scope)
    child_nodes = children(doc, scope_node)
    motion_node = None
    for n in child_nodes:
        if n['title'].endswith(": Motion log"):
            motion_node = n
            break

    doc_latest = {}
    if motion_node:
        for idx, row in table_rows(motion_node):
            obj_str = row['object']
            m = re.match(r'^(\d+)', obj_str)
            oid = f"Object {m.group(1)}" if m else obj_str
            frame = float(row['frame'])
            if frame <= start:
                doc_latest[oid] = (frame, {
                    'x': float(row['x']), 'y': float(row['y']),
                    'vx': float(row['vx']), 'vy': float(row['vy'])
                })

    state = {}
    for inp in inputs:
        oid = inp['entities'][0]
        t_in = float(inp['time'])
        if oid in doc_latest:
            frame_prev, s = doc_latest[oid]
            s = s.copy()
            dt = start - frame_prev
            if dt > 0:
                s['x'] += s['vx'] * dt * scale
                s['y'] += s['vy'] * dt * scale
                s['vx'] *= friction_rate ** dt
                s['vy'] *= friction_rate ** dt
            state[oid] = s
        else:
            s = {
                'x': float(inp['fields'].get('x', 0.0)),
                'y': float(inp['fields'].get('y', 0.0)),
                'vx': float(inp['fields'].get('vx', 0.0)),
                'vy': float(inp['fields'].get('vy', 0.0)),
            }
            dt = start - t_in
            if dt > 0:
                s['x'] += s['vx'] * dt * scale
                s['y'] += s['vy'] * dt * scale
                s['vx'] *= friction_rate ** dt
                s['vy'] *= friction_rate ** dt
            state[oid] = s

    future = {}
    for inp in inputs:
        t_in = float(inp['time'])
        if t_in > start:
            future[math.ceil(t_in)] = inp

    outcomes = []
    collided_pairs = set()
    t = math.ceil(start)
    end_t = math.ceil(horizon) + 1

    while t < end_t:
        for entry_t, inp in list(future.items()):
            if entry_t == t:
                oid = inp['entities'][0]
                state[oid] = {
                    'x': float(inp['fields'].get('x', 0.0)),
                    'y': float(inp['fields'].get('y', 0.0)),
                    'vx': float(inp['fields'].get('vx', 0.0)),
                    'vy': float(inp['fields'].get('vy', 0.0)),
                }
                del future[entry_t]

        if t > start + 0.5:
            oids = list(state.keys())
            for i in range(len(oids)):
                for j in range(i + 1, len(oids)):
                    o1, o2 = oids[i], oids[j]
                    s1, s2 = state[o1], state[o2]
                    dx = s2['x'] - s1['x']
                    dy = s2['y'] - s1['y']
                    dist = math.sqrt(dx * dx + dy * dy)
                    if dist < collision_thresh:
                        nx = dx / dist if dist > 1e-5 else 0
                        ny = dy / dist if dist > 1e-5 else 0
                        v1x, v1y = s1['vx'], s1['vy']
                        v2x, v2y = s2['vx'], s2['vy']
                        v_rel_x = v1x - v2x
                        v_rel_y = v1y - v2y
                        u = v_rel_x * nx + v_rel_y * ny
                        if u < 0:
                            pair = tuple(sorted([o1, o2]))
                            if pair not in collided_pairs:
                                collided_pairs.add(pair)
                                impulse = 0.5 * (1.0 + 0.0) * u
                                s1['vx'] = v1x - impulse * nx
                                s1['vy'] = v1y - impulse * ny
                                s2['vx'] = v2x + impulse * nx
                                s2['vy'] = v2y + impulse * ny
                                outcomes.append({
                                    'time': float(t),
                                    'kind': 'collision',
                                    'entities': [o1, o2],
                                    'value': None,
                                    'src': []
                                })

        for s in state.values():
            s['x'] += s['vx'] * scale
            s['y'] += s['vy'] * scale
            speed = math.sqrt(s['vx'] ** 2 + s['vy'] ** 2)
            if speed > 0.05:
                s['vx'] *= friction_rate
                s['vy'] *= friction_rate
            else:
                s['vx'] = 0.0
                s['vy'] = 0.0

        for oid in list(state.keys()):
            s = state[oid]
            if s['x'] < exit_x_min or s['x'] > exit_x_max or s['y'] < exit_y_min or s['y'] > exit_y_max:
                outcomes.append({
                    'time': float(t),
                    'kind': 'exit',
                    'entities': [oid],
                    'value': None,
                    'src': []
                })
                del state[oid]

        t += 1

    return outcomes

