            if obj_id in motion_rows:
                sorted_rows = sorted(motion_rows[obj_id], key=lambda x: float(x[1].get('frame', '0')))
                target_frame = ev['frame']
                best_row = None
                for r_idx, r_dict in sorted_rows:
                    r_frame = float(r_dict.get('frame', '0'))
                    if r_frame >= target_frame:
                        best_row = (r_idx, r_dict)
                        break
                if best_row is None and sorted_rows:
                    best_row = sorted_rows[0]

                if best_row:
                    r_idx, r_dict = best_row
                    src_locations.append([motion_node['node_id'], r_idx])
                    state_fields = get_state(r_dict)

            inputs_list.append({
                "id": f"input_{obj_id}",
                "time": float(ev['frame']),
                "kind": ev['type'],
                "entities": [obj_id],
                "fields": state_fields,
                "src": src_locations
            })
            processed_entities.add(obj_id)

    for obj_id, rows in motion_rows.items():
        if obj_id not in processed_entities and obj_id in entity_ids:
            sorted_rows = sorted(rows, key=lambda x: float(x[1].get('frame', '0')))
            if sorted_rows:
                first_idx, first_dict = sorted_rows[0]
                frame = float(first_dict.get('frame', 0))
                inputs_list.append({
                    "id": f"input_{obj_id}",
                    "time": frame,
                    "kind": "initial",
                    "entities": [obj_id],
                    "fields": get_state(first_dict),
                    "src": [[motion_node['node_id'], first_idx]]
                })
                processed_entities.add(obj_id)

    return inputs_list

