import math
import re
from collections import defaultdict

def _get_object_id(obj_str):
    m = re.match(r'^(\d+)', obj_str)
    return f"Object {m.group(1)}" if m else obj_str

def _find_node_by_suffix(nodes, suffix):
    for n in nodes:
        if n['title'].endswith(suffix):
            return n
    return None

def _get_motion_log(doc, scope):
    scope_node = node_by_title(doc, scope)
    if not scope_node:
        return {}
    child_nodes = children(doc, scope_node)
    motion_node = _find_node_by_suffix(child_nodes, ": Motion log")
    if not motion_node:
        return {}
    obj_data = defaultdict(list)
    for idx, row in table_rows(motion_node):
        oid = _get_object_id(row['object'])
        obj_data[oid].append({
            'frame': float(row['frame']),
            'x': float(row['x']), 'y': float(row['y']),
            'vx': float(row['vx']), 'vy': float(row['vy']),
            'speed': float(row['speed'])
        })
    for oid in obj_data:
        obj_data[oid].sort(key=lambda r: r['frame'])
    return obj_data

def _closest_frame(obj_records, target_time, prefer_earlier=True):
    best = None
    best_dist = float('inf')
    for r in obj_records:
        dist = abs(r['frame'] - target_time)
        if dist < best_dist or (dist == best_dist and prefer_earlier and r['frame'] <= target_time):
            best = r
            best_dist = dist
    return best

def simulate(doc, scope, inputs, params, start=None, horizon=None):
    rec_end = recorded_end(doc, scope)
    if horizon is None:
        horizon = rec_end if rec_end is not None else 128.0
    if start is None:
        start = 0.0

    # Scale factor: velocity * dt * scale = position change
    # Empirically from data: ~0.028 (about 1/36)
    SCALE = 0.028
    FRICTION = 0.99
    COLLISION_THRESH = 0.42
    EXIT_BOUND = 4.5

    motion_log = _get_motion_log(doc, scope)

    # Initialize state at start
    state = {}
    for inp in inputs:
        oid = inp['entities'][0]
        t_in = float(inp['time'])
        fields = inp.get('fields', {})

        if oid in motion_log and motion_log[oid]:
            r = _closest_frame(motion_log[oid], start)
            if r:
                s = {'x': r['x'], 'y': r['y'], 'vx': r['vx'], 'vy': r['vy']}
                # Propagate from recorded frame to start
                dt = start - r['frame']
                if dt > 0:
                    s['x'] += s['vx'] * dt * SCALE
                    s['y'] += s['vy'] * dt * SCALE
                    s['vx'] *= FRICTION ** dt
                    s['vy'] *= FRICTION ** dt
                elif dt < 0:
                    # Extrapolate backward
                    s['x'] -= s['vx'] * abs(dt) * SCALE
                    s['y'] -= s['vy'] * abs(dt) * SCALE
                    s['vx'] /= FRICTION ** abs(dt)
                    s['vy'] /= FRICTION ** abs(dt)
                state[oid] = s
            else:
                state[oid] = {
                    'x': float(fields.get('x', 0.0)),
                    'y': float(fields.get('y', 0.0)),
                    'vx': float(fields.get('vx', 0.0)),
                    'vy': float(fields.get('vy', 0.0)),
                }
        else:
            dt = start - t_in
            s = {
                'x': float(fields.get('x', 0.0)),
                'y': float(fields.get('y', 0.0)),
                'vx': float(fields.get('vx', 0.0)),
                'vy': float(fields.get('vy', 0.0)),
            }
            if dt > 0:
                s['x'] += s['vx'] * dt * SCALE
                s['y'] += s['vy'] * dt * SCALE
                s['vx'] *= FRICTION ** dt
                s['vy'] *= FRICTION ** dt
            state[oid] = s

    # Future entries
    future_entries = {}
    for inp in inputs:
        t_in = float(inp['time'])
        if t_in > start:
            future_entries[math.ceil(t_in)] = inp

    outcomes = []
    collided_pairs = set()
    active_ids = set(state.keys())

    t = math.ceil(start)
    end_t = max(math.ceil(horizon) + 1, t + 1)

    while t < end_t:
        # Process entries
        for entry_t, inp in list(future_entries.items()):
            if entry_t == t:
                oid = inp['entities'][0]
                fields = inp.get('fields', {})
                state[oid] = {
                    'x': float(fields.get('x', 0.0)),
                    'y': float(fields.get('y', 0.0)),
                    'vx': float(fields.get('vx', 0.0)),
                    'vy': float(fields.get('vy', 0.0)),
                }
                active_ids.add(oid)
                del future_entries[entry_t]

        if t >= start:
            # Collision detection
            ids = list(active_ids)
            for i in range(len(ids)):
                for j in range(i + 1, len(ids)):
                    o1, o2 = ids[i], ids[j]
                    s1, s2 = state[o1], state[o2]
                    dx = s2['x'] - s1['x']
                    dy = s2['y'] - s1['y']
                    dist = math.sqrt(dx * dx + dy * dy)

                    if dist < COLLISION_THRESH:
                        nx = dx / dist if dist > 1e-6 else 0
                        ny = dy / dist if dist > 1e-6 else 0

                        # Only collide if approaching
                        v1x, v1y = s1['vx'], s1['vy']
                        v2x, v2y = s2['vx'], s2['vy']
                        rel_vx = v1x - v2x
                        rel_vy = v1y - v2y
                        u = rel_vx * nx + rel_vy * ny

                        if u < 0:
                            pair = tuple(sorted([o1, o2]))
                            if pair not in collided_pairs:
                                collided_pairs.add(pair)
                                # Inelastic-ish collision: exchange some momentum
                                impulse = 0.5 * u  # coefficient of restitution ~0
                                s1['vx'] = v1x - impulse * nx
                                s1['vy'] = v1y - impulse * ny
                                s2['vx'] = v2x + impulse * nx
                                s2['vy'] = v2y + impulse * ny

                                outcomes.append({
                                    'time': float(t),
                                    'kind': 'collision',
                                    'entities': [o1, o2],
                                    'value': None,
                                    'src': []
                                })

        # Position and velocity update
        for oid in list(active_ids):
            s = state[oid]
            s['x'] += s['vx'] * SCALE
            s['y'] += s['vy'] * SCALE
            speed = math.sqrt(s['vx'] ** 2 + s['vy'] ** 2)
            if speed > 0.01:
                s['vx'] *= FRICTION
                s['vy'] *= FRICTION
            else:
                s['vx'] = 0.0
                s['vy'] = 0.0

        # Exit detection
        for oid in list(active_ids):
            s = state[oid]
            if abs(s['x']) > EXIT_BOUND or abs(s['y']) > EXIT_BOUND:
                outcomes.append({
                    'time': float(t),
                    'kind': 'exit',
                    'entities': [oid],
                    'value': None,
                    'src': []
                })
                active_ids.discard(oid)

        t += 1

    return outcomes

import re

