# ---- step 2: forward model ----
import math
import re
from collections import defaultdict

def _get_oid(obj_str):
    m = re.match(r'^(\d+)', obj_str)
    return f"Object {m.group(1)}" if m else obj_str

def _interpolate(r_list, target_frame):
    """Linearly interpolate position from motion log records."""
    if not r_list:
        return None
    if target_frame <= r_list[0]['frame']:
        return r_list[0].copy()
    if target_frame >= r_list[-1]['frame']:
        return r_list[-1].copy()
    for i in range(len(r_list) - 1):
        rp, rn = r_list[i], r_list[i + 1]
        if rp['frame'] <= target_frame <= rn['frame']:
            dt = rn['frame'] - rp['frame']
            if dt == 0:
                return rp.copy()
            t = (target_frame - rp['frame']) / dt
            return {
                'frame': target_frame,
                'x': rp['x'] + t * (rn['x'] - rp['x']),
                'y': rp['y'] + t * (rn['y'] - rp['y']),
                'vx': rp['vx'] + t * (rn['vx'] - rp['vx']),
                'vy': rp['vy'] + t * (rn['vy'] - rp['vy']),
            }
    return None

def simulate(doc, scope, inputs, params, start=None, horizon=None):
    rec_end = recorded_end(doc, scope)
    if horizon is None:
        horizon = rec_end if rec_end is not None else 128.0
    if start is None:
        start = 0.0

    # Gather motion log
    scope_node = node_by_title(doc, scope)
    child_nodes = children(doc, scope_node)
    motion_node = None
    for n in child_nodes:
        if n['title'].endswith(": Motion log"):
            motion_node = n
            break

    motion_log = defaultdict(list)
    if motion_node:
        for idx, row in table_rows(motion_node):
            oid = _get_oid(row['object'])
            motion_log[oid].append({
                'frame': float(row['frame']),
                'x': float(row['x']), 'y': float(row['y']),
                'vx': float(row['vx']), 'vy': float(row['vy']),
            })
    for oid in motion_log:
        motion_log[oid].sort(key=lambda r: r['frame'])

    # Determine active objects and their entry times from inputs
    active = {}
    for inp in inputs:
        oid = inp['entities'][0]
        t_in = float(inp['time'])
        active[oid] = {
            'entry': t_in,
            'init': inp['fields'].copy(),
        }

    COLLISION_THRESH = 0.41
    EXIT_THRESH = 4.2
    SCALE = 0.028
    FRICTION = 0.99

    def get_state(oid, t):
        recs = motion_log.get(oid, [])
        r = _interpolate(recs, t)
        if r is not None:
            return r
        # Fall back to physics propagation from input
        if oid in active:
            info = active[oid]
            s = dict(info['init'])
            dt = t - info['entry']
            if dt > 0:
                s['x'] = s.get('x', 0.0) + s.get('vx', 0.0) * dt * SCALE
                s['y'] = s.get('y', 0.0) + s.get('vy', 0.0) * dt * SCALE
                s['vx'] = s.get('vx', 0.0) * (FRICTION ** dt)
                s['vy'] = s.get('vy', 0.0) * (FRICTION ** dt)
            return s
        return None

    outcomes = []
    oids = sorted(active.keys())
    collided = set()

    t_start = int(math.ceil(start))
    t_end = int(math.ceil(horizon)) + 1

    for frame in range(t_start, t_end):
        # Collisions
        for i in range(len(oids)):
            for j in range(i + 1, len(oids)):
                o1, o2 = oids[i], oids[j]
                if active[o1]['entry'] > frame or active[o2]['entry'] > frame:
                    continue
                r1, r2 = get_state(o1, frame), get_state(o2, frame)
                if r1 is None or r2 is None:
                    continue
                dx = r2['x'] - r1['x']
                dy = r2['y'] - r1['y']
                dist = math.sqrt(dx * dx + dy * dy)
                if dist < COLLISION_THRESH:
                    pair = tuple(sorted([o1, o2]))
                    if pair not in collided:
                        collided.add(pair)
                        outcomes.append({
                            'time': float(frame),
                            'kind': 'collision',
                            'entities': [o1, o2],
                            'value': None,
                            'src': [],
                        })

        # Exits
        for oid in oids:
            if active[oid]['entry'] > frame:
                continue
            r = get_state(oid, frame)
            if r is None:
                continue
            if abs(r['x']) > EXIT_THRESH or abs(r['y']) > EXIT_THRESH:
                outcomes.append({
                    'time': float(frame),
                    'kind': 'exit',
                    'entities': [oid],
                    'value': None,
                    'src': [],
                })
                active[oid]['entry'] = frame + 1  # mark as handled

    outcomes.sort(key=lambda o: o['time'])
    return outcomes

# Let's analyze friction decay rates across multiple videos and objects
# We'll look at velocity changes per frame for objects moving without collisions

def analyze_friction(doc):
    scopes = ["Video 10017", "Video 10232", "Video 10517", "Video 10769", "Video 10967"]

    for scope in scopes:
        scope_node = node_by_title(doc, scope)
        if not scope_node:
            continue
        child_nodes = children(doc, scope_node)

        motion_node = None
        objects_node = None
        events_node = None
        for c in child_nodes:
            if c['title'].endswith(': Motion log'):
                motion_node = c
            if c['title'].endswith(': Objects'):
                objects_node = c
            if c['title'].endswith(': Events'):
                events_node = c

        if not motion_node or not objects_node:
            continue

        # Get object materials
        materials = {}
        for line in objects_node.get('lines', []):
            import re
            match = re.match(r'^Object (\d+): (\w+) (\w+) (\w+)', line)
            if match:
                obj_id = f"Object {match.group(1)}"
                material = match.group(3)
                materials[obj_id] = material

        # Get collision frames
        collision_frames = {}
        for line in events_node.get('lines', []):
            match = re.match(r'^Frame (\d+): Object (\d+) .* collides with Object (\d+)', line)
            if match:
                frame = int(match.group(1))
                obj1 = f"Object {match.group(2)}"
                obj2 = f"Object {match.group(3)}"
                if obj1 not in collision_frames:
                    collision_frames[obj1] = []
                if obj2 not in collision_frames:
                    collision_frames[obj2] = []
                collision_frames[obj1].append(frame)
                collision_frames[obj2].append(frame)

        # Analyze each object's friction
        rows = list(table_rows(motion_node))
        obj_data = {}
        for idx, row in rows:
            obj_str = row['object']
            match = re.match(r'^(\d+)', obj_str)
            if match:
                obj_id = f"Object {match.group(1)}"
                if obj_id not in obj_data:
                    obj_data[obj_id] = []
                obj_data[obj_id].append({
                    'frame': int(row['frame']),
                    'vx': float(row['vx']),
                    'vy': float(row['vy']),
                    'speed': float(row['speed'])
                })

        print(f"\n{scope}:")
        for obj_id, data in obj_data.items():
            material = materials.get(obj_id, 'unknown')
