import re
import math
import bisect
from collections import defaultdict

def _parse_object_id(obj_str):
    """Extract Object ID from string like '0 yellow metal sphere'"""
    match = re.match(r'^(\d+)', obj_str)
    if match:
        return f"Object {match.group(1)}"
    return obj_str

def _get_material_from_description(description):
    """Extract material from description like 'yellow metal sphere'"""
    parts = description.split()
    if 'metal' in parts:
        return 'metal'
    elif 'rubber' in parts:
        return 'rubber'
    return 'metal'  # default

def _get_mass(material):
    """Get mass based on material: metal is heavier than rubber"""
    if material == 'metal':
        return 1.0
    else:
        return 0.5  # rubber is lighter

def _compute_speed(vx, vy):
    return math.sqrt(vx*vx + vy*vy)

def _apply_friction(vx, vy, material, dt):
    """Apply friction: linear drag proportional to velocity"""
    speed = _compute_speed(vx, vy)
    if speed < 0.1:
        return 0.0, 0.0

    # Friction coefficient per frame - estimated from data
    if material == 'metal':
        mu = 0.008  # metal: low friction
    else:
        mu = 0.015  # rubber: higher friction

    # Scale friction by dt
    friction_factor = 1.0 - mu * dt

    if friction_factor < 0:
        friction_factor = 0

    new_vx = vx * friction_factor
    new_vy = vy * friction_factor

    new_speed = _compute_speed(new_vx, new_vy)
    if new_speed < 0.1:
        return 0.0, 0.0

    return new_vx, new_vy

def _collision_threshold(shape1, shape2):
    """Collision distance threshold based on shapes"""
    # Estimated radii for different shapes
    radius_map = {
        'sphere': 0.25,
        'cube': 0.20,
        'cylinder': 0.22
    }
    r1 = radius_map.get(shape1, 0.23)
    r2 = radius_map.get(shape2, 0.23)
    return r1 + r2

def _handle_collision(state1, state2, mass1, mass2, restitution=0.8):
    """Handle elastic collision between two objects"""
    x1, y1, vx1, vy1 = state1['x'], state1['y'], state1['vx'], state1['vy']
    x2, y2, vx2, vy2 = state2['x'], state2['y'], state2['vx'], state2['vy']

    # Collision normal (direction from obj2 to obj1)
    dx = x1 - x2
    dy = y1 - y2
    dist = math.sqrt(dx*dx + dy*dy)

    if dist < 0.001:
        # Objects are at the same position - use velocity direction as normal
        dvx = vx1 - vx2
        dvy = vy1 - vy2
        ddist = math.sqrt(dvx*dvx + dvy*dvy)
        if ddist < 0.001:
            return (x1, y1, vx1, vy1), (x2, y2, vx2, vy2)
        nx, ny = dvx/ddist, dvy/ddist
    else:
        nx, ny = dx/dist, dy/dist

    # Relative velocity along normal
    v_rel = (vx1 - vx2)*nx + (vy1 - vy2)*ny

    # Only process collision if objects are approaching
    if v_rel > 0:
        return (x1, y1, vx1, vy1), (x2, y2, vx2, vy2)

    # Impulse for collision (with restitution)
    impulse = -(1 + restitution) * v_rel / (1/mass1 + 1/mass2)

    # Update velocities
    new_vx1 = vx1 + impulse * nx / mass1
    new_vy1 = vy1 + impulse * ny / mass1
    new_vx2 = vx2 - impulse * nx / mass2
    new_vy2 = vy2 - impulse * ny / mass2

    # Separate objects to avoid sticking
    overlap = _collision_threshold(state1.get('shape', 'sphere'), state2.get('shape', 'sphere')) - dist
    if overlap > 0:
        sep = overlap * 0.5 + 0.01
        x1 += nx * sep
        y1 += ny * sep
        x2 -= nx * sep
        y2 -= ny * sep

    return (x1, y1, new_vx1, new_vy1), (x2, y2, new_vx2, new_vy2)

def simulate(doc, scope, inputs, params, start=None, horizon=None):
    """
    Forward model of the CLEVRER video simulation.

    Args:
        doc: The document dict
        scope: The scope title (e.g., 'Video 14996')
        inputs: List of input records
        params: Additional parameters
        start: Start time (default: 0)
        horizon: End time (default: recorded_end from doc)

    Returns:
        List of outcome records
    """
    # Get scope info
    scope_node = node_by_title(doc, scope)
    if not scope_node:
        return []

    child_nodes = children(doc, scope_node)

    # Get objects info
    objects_info = {}
    for c in child_nodes:
        if c['title'].endswith(': Objects'):
            for line in c.get('lines', []):
                m = re.match(r'^Object (\d+): (.+)', line)
                if m:
                    oid = f"Object {m.group(1)}"
                    desc = m.group(2)
                    # Parse color, material, shape
                    desc_m = re.match(r'^(\w+) (\w+) (\w+)', desc)
                    if desc_m:
                        color, material, shape = desc_m.group(1), desc_m.group(2), desc_m.group(3)
                    else:
                        color, material, shape = 'unknown', 'metal', 'sphere'
                    objects_info[oid] = {'color': color, 'material': material, 'shape': shape}

    # Get default horizon
    if horizon is None:
        horizon = recorded_end(doc, scope)
        if horizon is None:
            horizon = 127.0

    if start is None:
        start = 0.0

    # Build object states from inputs
    # Each object starts with its input state at its entry time
    objects = {}

    for inp in inputs:
        obj_id = inp['entities'][0] if inp['entities'] else None
        if obj_id is None:
            continue

        t = inp['time']
        fields = inp.get('fields', {})

        obj_info = objects_info.get(obj_id, {'material': 'metal', 'shape': 'sphere'})

        objects[obj_id] = {
            'x': fields.get('x', 0.0),
            'y': fields.get('y', 0.0),
            'vx': fields.get('vx', 0.0),
            'vy': fields.get('vy', 0.0),
            'material': obj_info['material'],
            'shape': obj_info['shape'],
            'active': True,
            'entered': t,
            'exited': None,
        }

    # Initialize state at start time
    # For objects that entered before start, extrapolate their position to start time
    for obj_id, obj in objects.items():
        if obj['entered'] < start:
            # Extrapolate position from entry to start
            dt = start - obj['entered']
            obj['x'] += obj['vx'] * dt
            obj['y'] += obj['vy'] * dt
            # Apply friction over this period
            obj['vx'], obj['vy'] = _apply_friction(obj['vx'], obj['vy'], obj['material'], dt)

    # Event-driven simulation
    outcomes = []
    current_time = start
    processed_collisions = set()

    while current_time < horizon:
        # Find next event (entry or collision)
        next_event_time = horizon
        next_event = None

        # Check for entries after current time
        for inp in inputs:
            t = inp['time']
            if t > current_time and t < next_event_time:
                next_event_time = t
                next_event = ('entry', inp)

        # Check for potential collisions
        obj_ids = list(objects.keys())
        for i in range(len(obj_ids)):
            for j in range(i+1, len(obj_ids)):
                o1 = objects[obj_ids[i]]
                o2 = objects[obj_ids[j]]

                if not o1['active'] or not o2['active']:
                    continue

                # Skip if already collided at current time
                collision_key = tuple(sorted([obj_ids[i], obj_ids[j]]))
                if collision_key in processed_collisions:
                    continue

                # Check if objects will collide
                x1, y1, vx1, vy1 = o1['x'], o1['y'], o1['vx'], o1['vy']
                x2, y2, vx2, vy2 = o2['x'], o2['y'], o2['vx'], o2['vy']

                # Relative position and velocity
                dx = x2 - x1
                dy = y2 - y1
                dvx = vx2 - vx1
                dvy = vy2 - vy1

                # Current distance
                current_dist = math.sqrt(dx*dx + dy*dy)

                # Collision threshold
                threshold = _collision_threshold(o1['shape'], o2['shape'])

                # Check if currently colliding
                if current_dist <= threshold:
                    # Immediate collision
                    next_event_time = current_time
                    next_event = ('collision', obj_ids[i], obj_ids[j])
                    break

                # Find when objects will be closest (solve quadratic)
                # Distance^2 = (dx + dvx*t)^2 + (dy + dvy*t)^2
                # Minimize this: 2*dvx*(dx + dvx*t) + 2*dvy*(dy + dvy*t) = 0
                # t_closest = -(dx*dvx + dy*dvy) / (dvx^2 + dvy^2)

                dv_sq = dvx*dvx + dvy*dvy
                if dv_sq > 0.0001:
                    t_closest = -(dx*dvx + dy*dvy) / dv_sq

                    if t_closest > 0.01:  # Future collision
                        # Distance at closest approach
                        x_c = dx + dvx * t_closest
                        y_c = dy + dvy * t_closest
                        dist_closest = math.sqrt(x_c*x_c + y_c*y_c)

                        # If they get close enough, estimate collision time
                        if dist_closest <= threshold:
                            # Solve for when distance = threshold
                            # (dx + dvx*t)^2 + (dy + dvy*t)^2 = threshold^2
                            a = dv_sq
                            b = 2*(dx*dvx + dy*dvy)
                            c = dx*dx + dy*dy - threshold*threshold

                            discriminant = b*b - 4*a*c
                            if discriminant >= 0:
                                t1 = (-b - math.sqrt(discriminant)) / (2*a)
                                t2 = (-b + math.sqrt(discriminant)) / (2*a)

                                # First positive time
                                if t1 > 0.01 and t1 < next_event_time:
                                    next_event_time = current_time + t1
                                    next_event = ('collision', obj_ids[i], obj_ids[j])
                                elif t2 > 0.01 and t2 < next_event_time:
                                    next_event_time = current_time + t2
                                    next_event = ('collision', obj_ids[i], obj_ids[j])

            if next_event and next_event[0] == 'collision':
                break

        # Advance time to next event
        dt = next_event_time - current_time

        if dt < 0.01:
            dt = 0.01

        # Apply friction to all objects for dt
        for obj in objects.values():
            if obj['active']:
                obj['vx'], obj['vy'] = _apply_friction(obj['vx'], obj['vy'], obj['material'], dt)
                obj['x'] += obj['vx'] * dt
                obj['y'] += obj['vy'] * dt

        current_time = next_event_time

        # Process the event
        if next_event is None:
            break

        event_type = next_event[0]

        if event_type == 'entry':
            inp = next_event[1]
            obj_id = inp['entities'][0] if inp['entities'] else None
            if obj_id and obj_id not in objects:
                fields = inp.get('fields', {})
                obj_info = objects_info.get(obj_id, {'material': 'metal', 'shape': 'sphere'})
                objects[obj_id] = {
                    'x': fields.get('x', 0.0),
                    'y': fields.get('y', 0.0),
                    'vx': fields.get('vx', 0.0),
                    'vy': fields.get('vy', 0.0),
                    'material': obj_info['material'],
                    'shape': obj_info['shape'],
                    'active': True,
                    'entered': inp['time'],
                    'exited': None,
                }

        elif event_type == 'collision':
            obj1_id = next_event[1]
            obj2_id = next_event[2]

            o1 = objects[obj1_id]
            o2 = objects[obj2_id]

            if o1['active'] and o2['active']:
                mass1 = _get_mass(o1['material'])
                mass2 = _get_mass(o2['material'])

                # Determine restitution based on materials
                if o1['material'] == 'metal' and o2['material'] == 'metal':
                    restitution = 0.9
                elif o1['material'] == 'rubber' and o2['material'] == 'rubber':
                    restitution = 0.6
                else:
                    restitution = 0.75

                state1 = {k: o1[k] for k in ['x', 'y', 'vx', 'vy', 'shape']}
                state2 = {k: o2[k] for k in ['x', 'y', 'vx', 'vy', 'shape']}

                (new_x1, new_y1, new_vx1, new_vy1), (new_x2, new_y2, new_vx2, new_vy2) = \
                    _handle_collision(state1, state2, mass1, mass2, restitution)

                o1['x'], o1['y'], o1['vx'], o1['vy'] = new_x1, new_y1, new_vx1, new_vy1
                o2['x'], o2['y'], o2['vx'], o2['vy'] = new_x2, new_y2, new_vx2, new_vy2

                processed_collisions.add(tuple(sorted([obj1_id, obj2_id])))

                # Record collision outcome
                if current_time > start:
                    outcomes.append({
                        'time': round(current_time),
                        'kind': 'collision',
                        'entities': sorted([obj1_id, obj2_id]),
                        'value': None,
                        'src': []
                    })

        # Check for exits (objects going out of bounds)
        # CLEVRER scene bounds are roughly [-4, 4] x [-4, 4]
        for obj_id, obj in objects.items():
            if obj['active'] and obj['exited'] is None:
                if obj['x'] < -4.5 or obj['x'] > 4.5 or obj['y'] < -4.5 or obj['y'] > 4.5:
                    obj['exited'] = current_time
                    obj['active'] = False
                    if current_time > start:
                        outcomes.append({
                            'time': round(current_time),
                            'kind': 'exit',
                            'entities': [obj_id],
                            'value': None,
                            'src': []
                        })

    # Sort outcomes by time
    outcomes.sort(key=lambda x: x['time'])

    return outcomes

import re

def _find_node_by_suffix(nodes, suffix):
    for node in nodes:
        if node['title'].endswith(suffix):
            return node
    return None

def _get_object_id_from_string(obj_str):
    match = re.match(r'^(\d+)', obj_str)
    if match:
        return f"Object {match.group(1)}"
    return obj_str

def entities(doc, scope):
    scope_node = node_by_title(doc, scope)
    if not scope_node:
        return []
    child_nodes = children(doc, scope_node)
    objects_node = _find_node_by_suffix(child_nodes, ": Objects")

    result = []
    if objects_node and objects_node.get('kind') == 'list':
        for line in objects_node.get('lines', []):
            match = re.match(r'^Object (\d+): (.+)', line)
            if match:
                result.append({
                    "id": f"Object {match.group(1)}",
