import re
import math
from collections import defaultdict

def _parse_object_id(obj_str):
    match = re.match(r'^(\d+)', obj_str)
    if match:
        return f"Object {match.group(1)}"
    return obj_str

def simulate(doc, scope, inputs, params, start=None, horizon=None):
    """
    Forward model of the CLEVRER video simulation.
    """
    scope_node = node_by_title(doc, scope)
    if not scope_node:
        return []

    child_nodes = children(doc, scope_node)

    # Get objects info
    objects_info = {}
    for c in child_nodes:
        if c['title'].endswith(': Objects'):
            for line in c.get('lines', []):
                m = re.match(r'^Object (\d+): (\w+) (\w+) (\w+)', line)
                if m:
                    oid = f"Object {m.group(1)}"
                    color, material, shape = m.group(2), m.group(3), m.group(4)
                    objects_info[oid] = {'color': color, 'material': material, 'shape': shape}

    # Get default horizon
    if horizon is None:
        horizon = recorded_end(doc, scope)
        if horizon is None:
            horizon = 127.0

    if start is None:
        start = 0.0

    # Build object states from inputs
    objects = {}
    entry_times = {}

    for inp in inputs:
        if not inp.get('entities'):
            continue
        obj_id = inp['entities'][0]
        t = inp['time']
        fields = inp.get('fields', {})

        obj_info = objects_info.get(obj_id, {'material': 'metal', 'shape': 'sphere'})

        objects[obj_id] = {
            'x': fields.get('x', 0.0),
            'y': fields.get('y', 0.0),
            'vx': fields.get('vx', 0.0),
            'vy': fields.get('vy', 0.0),
            'material': obj_info['material'],
            'shape': obj_info['shape'],
            'active': True,
            'entered': t,
            'exited': None,
        }
        entry_times[obj_id] = t

    # Initialize state at start time
    for obj_id, obj in objects.items():
        if obj['entered'] < start:
            dt = start - obj['entered']
            # Apply friction
            if obj['material'] == 'metal':
                friction_rate = 0.005
            else:
                friction_rate = 0.012

            speed = math.sqrt(obj['vx']**2 + obj['vy']**2)
            if speed > 0.05:
                decel = friction_rate * dt
                if decel < speed:
                    scale = (speed - decel) / speed
                    obj['vx'] *= scale
                    obj['vy'] *= scale
                else:
                    obj['vx'] = 0.0
                    obj['vy'] = 0.0

            obj['x'] += obj['vx'] * dt
            obj['y'] += obj['vy'] * dt

    # Simulation
    outcomes = []
    current_time = start
    processed_collisions = set()
    processed_entries = set()

    COLLISION_DIST = 0.48
    max_iterations = 1000
    iteration = 0

    while current_time < horizon and iteration < max_iterations:
        iteration += 1

        # Find next event
        next_event_time = horizon
        next_event = None

        # Check for entries not yet processed
        for inp in inputs:
            obj_id = inp['entities'][0] if inp.get('entities') else None
            t = inp['time']
            if obj_id and obj_id not in processed_entries and t > current_time:
                if t < next_event_time:
                    next_event_time = t
                    next_event = ('entry', inp)

        # Check for collisions
        obj_ids = [oid for oid, obj in objects.items() 
                   if obj['active'] and obj['exited'] is None and obj['entered'] <= current_time]

        for i in range(len(obj_ids)):
            for j in range(i+1, len(obj_ids)):
                o1 = objects[obj_ids[i]]
                o2 = objects[obj_ids[j]]

                pair = tuple(sorted([obj_ids[i], obj_ids[j]]))
                if pair in processed_collisions:
                    continue

                x1, y1, vx1, vy1 = o1['x'], o1['y'], o1['vx'], o1['vy']
                x2, y2, vx2, vy2 = o2['x'], o2['y'], o2['vx'], o2['vy']

                dx = x2 - x1
                dy = y2 - y1
                dist = math.sqrt(dx*dx + dy*dy)

                # If currently colliding
                if dist <= COLLISION_DIST:
                    if current_time < next_event_time:
                        next_event_time = current_time
                        next_event = ('collision', obj_ids[i], obj_ids[j])
                    break

                # Predict collision
                dvx = vx2 - vx1
                dvy = vy2 - vy1
                dv_sq = dvx*dvx + dvy*dvy

                if dv_sq > 0.000001:
                    a = dv_sq
                    b = 2*(dx*dvx + dy*dvy)
                    c = dx*dx + dy*dy - COLLISION_DIST*COLLISION_DIST

                    disc = b*b - 4*a*c
                    if disc >= 0:
                        sqrt_disc = math.sqrt(disc)
                        t1 = (-b - sqrt_disc) / (2*a)

                        if t1 > 0.5:  # Need at least 0.5 frames gap
                            candidate_time = current_time + t1
                            if candidate_time < next_event_time:
                                next_event_time = candidate_time
                                next_event = ('collision', obj_ids[i], obj_ids[j])

            if next_event and next_event[0] == 'collision':
                break

        if next_event is None:
            break

        # Advance time
        dt = next_event_time - current_time
        if dt < 0:
            dt = 0
        if dt > 128:
            dt = 128

        # Apply friction and move objects
        for obj in objects.values():
            if obj['active'] and obj['exited'] is None and obj['entered'] <= current_time:
                speed = math.sqrt(obj['vx']**2 + obj['vy']**2)

                if speed > 0.1:
                    friction_rate = 0.005 if obj['material'] == 'metal' else 0.012
                    decel = friction_rate * dt
                    if decel < speed:
                        scale = (speed - decel) / speed
                        obj['vx'] *= scale
                        obj['vy'] *= scale
                    else:
                        obj['vx'] = 0.0
                        obj['vy'] = 0.0

                obj['x'] += obj['vx'] * dt
                obj['y'] += obj['vy'] * dt

        current_time = next_event_time

        # Process the event
        event_type = next_event[0]

        if event_type == 'entry':
            inp = next_event[1]
            obj_id = inp['entities'][0]
            fields = inp.get('fields', {})
            obj_info = objects_info.get(obj_id, {'material': 'metal', 'shape': 'sphere'})
            objects[obj_id] = {
                'x': fields.get('x', 0.0),
                'y': fields.get('y', 0.0),
                'vx': fields.get('vx', 0.0),
                'vy': fields.get('vy', 0.0),
                'material': obj_info['material'],
                'shape': obj_info['shape'],
                'active': True,
                'entered': inp['time'],
                'exited': None,
            }
            processed_entries.add(obj_id)

        elif event_type == 'collision':
            obj1_id, obj2_id = next_event[1], next_event[2]
            o1 = objects[obj1_id]
            o2 = objects[obj2_id]

            if not o1['active'] or not o2['active']:
                continue

            x1, y1, vx1, vy1 = o1['x'], o1['y'], o1['vx'], o1['vy']
            x2, y2, vx2, vy2 = o2['x'], o2['y'], o2['vx'], o2['vy']

            dx = x2 - x1
            dy = y2 - y1
            dist = math.sqrt(dx*dx + dy*dy)

            if dist < 0.001:
                dvx = vx2 - vx1
                dvy = vy2 - vy1
                ddist = math.sqrt(dvx*dvx + dvy*dvy)
                if ddist > 0.001:
                    nx, ny = dvx/ddist, dvy/ddist
                else:
                    nx, ny = 1, 0
            else:
                nx, ny = dx/dist, dy/dist

            v_rel = (vx1 - vx2)*nx + (vy1 - vy2)*ny

            mass1 = 1.0 if o1['material'] == 'metal' else 0.5
            mass2 = 1.0 if o2['material'] == 'metal' else 0.5

            if o1['material'] == 'metal' and o2['material'] == 'metal':
                e = 0.9
            elif o1['material'] == 'rubber' and o2['material'] == 'rubber':
                e = 0.4
            else:
                e = 0.65

            if v_rel < 0:
                j = -(1 + e) * v_rel / (1/mass1 + 1/mass2)
                new_vx1 = vx1 + j * nx / mass1
                new_vy1 = vy1 + j * ny / mass1
                new_vx2 = vx2 - j * nx / mass2
                new_vy2 = vy2 - j * ny / mass2

                if dist < COLLISION_DIST:
                    sep = (COLLISION_DIST - dist) * 0.5 + 0.02
                    o1['x'] = x1 - nx * sep
                    o1['y'] = y1 - ny * sep
                    o2['x'] = x2 + nx * sep
                    o2['y'] = y2 + ny * sep
                else:
                    o1['x'], o1['y'] = x1, y1
                    o2['x'], o2['y'] = x2, y2

                o1['vx'], o1['vy'] = new_vx1, new_vy1
                o2['vx'], o2['vy'] = new_vx2, new_vy2

            outcomes.append({
                'time': round(current_time),
                'kind': 'collision',
                'entities': sorted([obj1_id, obj2_id]),
                'value': None,
                'src': []
            })
            processed_collisions.add(tuple(sorted([obj1_id, obj2_id])))

        # Check for exits
        for obj_id, obj in objects.items():
            if obj['active'] and obj['exited'] is None:
                if obj['x'] < -5.0 or obj['x'] > 5.0 or obj['y'] < -5.0 or obj['y'] > 5.0:
                    obj['exited'] = current_time
                    obj['active'] = False
                    outcomes.append({
                        'time': round(current_time),
                        'kind': 'exit',
                        'entities': [obj_id],
                        'value': None,
                        'src': []
                    })

    outcomes.sort(key=lambda x: (x['time'], x['kind'], x['entities']))
    return outcomes

