    while current_time < horizon and max_frames > 0:
        max_frames -= 1

        # Determine step size - advance to next integer frame or entry time
        next_times = []

        # Next integer frame
        next_frame = math.ceil(current_time) if current_time != int(current_time) else current_time + 1
        if next_frame <= horizon:
            next_times.append(next_frame)

        # Entry times
        for obj_id, entry in object_entries.items():
            et = entry['entry_time']
            if et > current_time and et <= horizon:
                next_times.append(et)

        # Collision predictions
        for i, (oid1, o1) in enumerate(objects.items()):
            if o1['exited'] or current_time < o1['entry_time']:
                continue
            for oid2, o2 in list(objects.items())[i+1:]:
                if o2['exited'] or current_time < o2['entry_time']:
                    continue
                pair = tuple(sorted([oid1, oid2]))
                if pair in processed_collisions:
                    continue

                dx = o2['x'] - o1['x']
                dy = o2['y'] - o1['y']
                dist = math.sqrt(dx*dx + dy*dy)

                # Currently colliding?
                if dist <= COLLISION_DIST:
                    next_times.append(current_time)
                    continue

                # Predict collision time
                dvx = o2['vx'] - o1['vx']
                dvy = o2['vy'] - o1['vy']
                dv_sq = dvx*dvx + dvy*dvy

                if dv_sq > 0.0001:
                    a = dv_sq
                    b = 2*(dx*dvx + dy*dvy)
                    c = dx*dx + dy*dy - COLLISION_DIST*COLLISION_DIST
                    disc = b*b - 4*a*c
                    if disc >= 0:
                        sqrt_disc = math.sqrt(disc)
                        t1 = (-b - sqrt_disc) / (2*a)
                        if t1 > 0.5:
                            candidate = current_time + t1
                            if candidate <= horizon:
                                next_times.append(candidate)

        if not next_times:
            break

        next_time = min(t for t in next_times if t > current_time + 0.001)
        if next_time == current_time:
            next_time = current_time + 1

        if next_time > horizon:
            next_time = horizon

        dt = next_time - current_time
        if dt < 0:
            dt = 0

        # Apply friction and move
        for obj in objects.values():
            if obj['exited'] or current_time < obj['entry_time']:
                continue

            speed = math.sqrt(obj['vx']**2 + obj['vy']**2)

            if speed > 0.1:
                friction = FRICTION_METAL if obj['material'] == 'metal' else FRICTION_RUBBER
                decel = friction * dt
                if decel < speed:
                    scale = (speed - decel) / speed
                    obj['vx'] *= scale
                    obj['vy'] *= scale
                else:
                    obj['vx'] = 0.0
                    obj['vy'] = 0.0

            obj['x'] += obj['vx'] * dt
            obj['y'] += obj['vy'] * dt

        # Activate newly entered objects
        for obj_id, entry in object_entries.items():
            if entry['entry_time'] <= next_time and entry['entry_time'] > current_time:
                obj = objects[obj_id]
                obj['x'] = entry['entry_x']
                obj['y'] = entry['entry_y']
                obj['vx'] = entry['entry_vx']
                obj['vy'] = entry['entry_vy']

        current_time = next_time

        # Check for collisions at current time
        for i, (oid1, o1) in enumerate(objects.items()):
            if o1['exited'] or current_time < o1['entry_time']:
                continue
            for oid2, o2 in list(objects.items())[i+1:]:
                if o2['exited'] or current_time < o2['entry_time']:
                    continue
                pair = tuple(sorted([oid1, oid2]))
                if pair in processed_collisions:
                    continue

                dx = o2['x'] - o1['x']
                dy = o2['y'] - o1['y']
                dist = math.sqrt(dx*dx + dy*dy)

                if dist <= COLLISION_DIST:
                    # Handle collision
                    x1, y1, vx1, vy1 = o1['x'], o1['y'], o1['vx'], o1['vy']
                    x2, y2, vx2, vy2 = o2['x'], o2['y'], o2['vx'], o2['vy']

                    if dist < 0.001:
                        dvx = vx2 - vx1
                        dvy = vy2 - vy1
                        ddist = math.sqrt(dvx*dvx + dvy*dvy)
                        if ddist > 0.001:
                            nx, ny = dvx/ddist, dvy/ddist
                        else:
                            nx, ny = 1, 0
                    else:
                        nx, ny = dx/dist, dy/dist

                    v_rel = (vx1 - vx2)*nx + (vy1 - vy2)*ny

                    m1 = get_mass(o1['material'])
                    m2 = get_mass(o2['material'])
                    e = get_restitution(o1['material'], o2['material'])

                    if v_rel < 0:
                        j = -(1 + e) * v_rel / (1/m1 + 1/m2)
                        new_vx1 = vx1 + j * nx / m1
                        new_vy1 = vy1 + j * ny / m1
                        new_vx2 = vx2 - j * nx / m2
                        new_vy2 = vy2 - j * ny / m2

                        sep = (COLLISION_DIST - dist) * 0.5 + 0.02
                        o1['x'] = x1 - nx * sep
                        o1['y'] = y1 - ny * sep
                        o2['x'] = x2 + nx * sep
                        o2['y'] = y2 + ny * sep

                        o1['vx'], o1['vy'] = new_vx1, new_vy1
                        o2['vx'], o2['vy'] = new_vx2, new_vy2

                    outcomes.append({
                        'time': round(current_time),
                        'kind': 'collision',
                        'entities': sorted([oid1, oid2]),
                        'value': None,
                        'src': []
                    })
                    processed_collisions.add(pair)

    # Filter outcomes to only those after start
    outcomes = [o for o in outcomes if o['time'] >= start]

    outcomes.sort(key=lambda x: (x['time'], x['kind'], x['entities']))
    return outcomes

