import math

def simulate(doc, scope, inputs, params, start=None, horizon=None):
    rec_end = recorded_end(doc, scope)
    if horizon is None:
        horizon = rec_end if rec_end is not None else 127.0
    if start is None:
        start = 0.0

    objects = {}
    pending = sorted([inp for inp in inputs if inp['time'] > start], key=lambda x: x['time'])

    # Initialize state at `start` from inputs at or before `start`
    for inp in inputs:
        if inp['time'] <= start:
            oid = inp['entities'][0]
            dt = start - inp['time']
            objects[oid] = {
                'x': inp['fields']['x'] + inp['fields']['vx'] * dt,
                'y': inp['fields']['y'] + inp['fields']['vy'] * dt,
                'vx': inp['fields']['vx'],
                'vy': inp['fields']['vy'],
                'exited': False
            }

    outcomes = []
    collided = set()
    t = start

    while t <= horizon:
        step = min(0.5, horizon - t)
        if step < 1e-9:
            break

        # Activate objects entering during this step
        while pending and pending[0]['time'] <= t + step:
            inp = pending.pop(0)
            oid = inp['entities'][0]
            objects[oid] = {
                'x': inp['fields']['x'],
                'y': inp['fields']['y'],
                'vx': inp['fields']['vx'],
                'vy': inp['fields']['vy'],
                'exited': False
            }

        # Update positions
        for oid, obj in objects.items():
            if not obj['exited']:
                obj['x'] += obj['vx'] * step
                obj['y'] += obj['vy'] * step

                # Check exit bounds (approximate CLEVRER viewport)
                if abs(obj['x']) > 5.0 or abs(obj['y']) > 5.0:
                    obj['exited'] = True
                    outcomes.append({
                        'time': float(int(round(t + step))),
                        'kind': 'exit',
                        'entities': [oid],
                        'value': None,
                        'src': []
                    })

        # Check collisions
        oids = list(objects.keys())
        for i in range(len(oids)):
            for j in range(i+1, len(oids)):
                o1, o2 = oids[i], oids[j]
                if objects[o1]['exited'] or objects[o2]['exited']:
                    continue
                if (o1, o2) in collided or (o2, o1) in collided:
                    continue

                dx = objects[o1]['x'] - objects[o2]['x']
                dy = objects[o1]['y'] - objects[o2]['y']
                d = math.hypot(dx, dy)

                # Collision threshold calibrated from CLEVRER object sizes
                if d < 0.45:
                    collided.add((o1, o2))
                    collided.add((o2, o1))
                    outcomes.append({
                        'time': float(int(round(t + step))),
                        'kind': 'collision',
                        'entities': [o1, o2],
                        'value': None,
                        'src': []
                    })

                    # Simple elastic collision response (equal mass approximation)
                    nx, ny = dx/d, dy/d
                    v1n = objects[o1]['vx']*nx + objects[o1]['vy']*ny
                    v2n = objects[o2]['vx']*nx + objects[o2]['vy']*ny

                    objects[o1]['vx'] += (v2n - v1n) * nx
                    objects[o1]['vy'] += (v2n - v1n) * ny
                    objects[o2]['vx'] += (v1n - v2n) * nx
                    objects[o2]['vy'] += (v1n - v2n) * ny

        t += step

    return outcomes

