                'vx': inp['fields']['vx'], 'vy': inp['fields']['vy'],
                'exited': False
            }

        # Update positions
        for oid, obj in objects.items():
            if not obj['exited']:
                obj['x'] += obj['vx'] * curr_step
                obj['y'] += obj['vy'] * curr_step
                # CLEVRER viewport bounds approximation
                if abs(obj['x']) > 5.0 or abs(obj['y']) > 5.0:
                    obj['exited'] = True
                    outcomes.append({
                        'time': float(round(t + curr_step)),
                        'kind': 'exit',
                        'entities': [oid],
                        'value': None,
                        'src': []
                    })

        # Check collisions
        oids = list(objects.keys())
        for i in range(len(oids)):
            for j in range(i+1, len(oids)):
                o1, o2 = oids[i], oids[j]
                if objects[o1]['exited'] or objects[o2]['exited']:
                    continue
                if (o1, o2) in collided:
                    continue

                dx = objects[o1]['x'] - objects[o2]['x']
                dy = objects[o1]['y'] - objects[o2]['y']
                d = math.hypot(dx, dy)

                # Collision threshold calibrated from CLEVRER object sizes
                if d < 0.45 and d > 1e-6:
                    collided.add((o1, o2))
                    outcomes.append({
                        'time': float(round(t + curr_step)),
                        'kind': 'collision',
                        'entities': [o1, o2],
                        'value': None,
                        'src': []
                    })

                    # Elastic collision response (equal mass approximation)
                    nx, ny = dx/d, dy/d
                    dvx = objects[o1]['vx'] - objects[o2]['vx']
                    dvy = objects[o1]['vy'] - objects[o2]['vy']
                    dot = dvx * nx + dvy * ny

                    objects[o1]['vx'] -= dot * nx
                    objects[o1]['vy'] -= dot * ny
                    objects[o2]['vx'] += dot * nx
                    objects[o2]['vy'] += dot * ny

                    # Separate slightly to prevent sticking/re-triggering
                    overlap = 0.45 - d
                    objects[o1]['x'] -= nx * overlap / 2
                    objects[o1]['y'] -= ny * overlap / 2
                    objects[o2]['x'] += nx * overlap / 2
                    objects[o2]['y'] += ny * overlap / 2

        t += curr_step

    return outcomes

