def simulate(doc, scope, inputs, params, start=None, horizon=None):
    rec_end = recorded_end(doc, scope)
    if horizon is None:
        horizon = rec_end if rec_end is not None else 127.0
    if start is None:
        start = 0.0

    sorted_inputs = sorted(inputs, key=lambda x: x['time'])
    t_min = sorted_inputs[0]['time'] if sorted_inputs else 0.0

    objects = {}
    pending = []
    for inp in sorted_inputs:
        t = inp['time']
        oid = inp['entities'][0]
        if t <= t_min:
            objects[oid] = {
                'x': inp['fields']['x'], 'y': inp['fields']['y'],
                'vx': inp['fields']['vx'], 'vy': inp['fields']['vy'],
                'exited': False
            }
        else:
            pending.append((t, inp))

    outcomes = []
    collided = set()
    t = t_min
    step = 0.05

    while t <= horizon:
        dt = min(step, horizon - t)
        if dt < 1e-6:
            break

        # Activate objects that enter during this step
        while pending and pending[0][0] <= t + dt:
            _, inp = pending.pop(0)
            oid = inp['entities'][0]
            objects[oid] = {
                'x': inp['fields']['x'], 'y': inp['fields']['y'],
                'vx': inp['fields']['vx'], 'vy': inp['fields']['vy'],
                'exited': False
            }

        # Update positions
        for oid, obj in objects.items():
            if not obj['exited']:
                obj['x'] += obj['vx'] * dt
                obj['y'] += obj['vy'] * dt

                # Exit detection (approximate CLEVRER viewport bounds)
                if abs(obj['x']) > 4.5 or abs(obj['y']) > 4.5:
                    obj['exited'] = True
                    if t > start:
                        outcomes.append({
                            'time': float(round(t)),
                            'kind': 'exit',
                            'entities': [oid],
                            'value': None,
                            'src': []
                        })

        # Collision detection and response
        oids = list(objects.keys())
        for i in range(len(oids)):
            for j in range(i + 1, len(oids)):
                o1, o2 = oids[i], oids[j]
                if objects[o1]['exited'] or objects[o2]['exited']:
                    continue
                if (o1, o2) in collided:
                    continue

                dx = objects[o1]['x'] - objects[o2]['x']
                dy = objects[o1]['y'] - objects[o2]['y']
                d = math.hypot(dx, dy)

                # Collision threshold estimated from CLEVRER object sizes
                if d < 0.45 and d > 1e-6:
                    collided.add((o1, o2))
                    if t > start:
                        outcomes.append({
                            'time': float(round(t)),
                            'kind': 'collision',
                            'entities': [o1, o2],
                            'value': None,
                            'src': []
                        })

                    # Elastic collision response (equal mass approximation)
                    nx, ny = dx / d, dy / d
                    dvx = objects[o1]['vx'] - objects[o2]['vx']
                    dvy = objects[o1]['vy'] - objects[o2]['vy']
                    dot = dvx * nx + dvy * ny

                    objects[o1]['vx'] -= dot * nx
                    objects[o1]['vy'] -= dot * ny
                    objects[o2]['vx'] += dot * nx
                    objects[o2]['vy'] += dot * ny

                    # Separate slightly to prevent sticking/re-triggering
                    overlap = 0.45 - d
                    objects[o1]['x'] -= nx * overlap / 2
                    objects[o1]['y'] -= ny * overlap / 2
                    objects[o2]['x'] += nx * overlap / 2
                    objects[o2]['y'] += ny * overlap / 2

        t += dt

    return outcomes

