            oid = inp['entities'][0]
            objects[oid] = {
                'x': inp['fields']['x'], 'y': inp['fields']['y'],
                'vx': inp['fields']['vx'], 'vy': inp['fields']['vy'],
                'exited': False
            }

        # Update positions by one step
        for oid, obj in objects.items():
            if not obj['exited']:
                obj['x'] += obj['vx'] * step
                obj['y'] += obj['vy'] * step

                # Exit detection
                if abs(obj['x']) > 5.0 or abs(obj['y']) > 5.0:
                    obj['exited'] = True
                    outcomes.append({
                        'time': float(t),
                        'kind': 'exit',
                        'entities': [oid],
                        'value': None,
                        'src': []
                    })

        # Check collisions
        oids = list(objects.keys())
        for i in range(len(oids)):
            for j in range(i+1, len(oids)):
                o1, o2 = oids[i], oids[j]
                if objects[o1]['exited'] or objects[o2]['exited']:
                    continue
                if (o1, o2) in collided:
                    continue

                dx = objects[o1]['x'] - objects[o2]['x']
                dy = objects[o1]['y'] - objects[o2]['y']
                d = math.hypot(dx, dy)

                if d < collision_dist:
                    collided.add((o1, o2))
                    outcomes.append({
                        'time': float(t),
                        'kind': 'collision',
                        'entities': [o1, o2],
                        'value': None,
                        'src': []
                    })

                    # Simple elastic collision response
                    if d > 1e-6:
                        nx, ny = dx/d, dy/d
                        dvx = objects[o1]['vx'] - objects[o2]['vx']
                        dvy = objects[o1]['vy'] - objects[o2]['vy']
                        dot = dvx*nx + dvy*ny
                        objects[o1]['vx'] -= dot*nx
                        objects[o1]['vy'] -= dot*ny
                        objects[o2]['vx'] += dot*nx
                        objects[o2]['vy'] += dot*ny

        t += step

    return outcomes

import re

def _find_node_by_suffix(nodes, suffix):
    for node in nodes:
        if node['title'].endswith(suffix):
            return node
    return None

def _get_object_id_from_string(obj_str):
    match = re.match(r'^(\d+)', obj_str)
    if match:
        return f"Object {match.group(1)}"
    return obj_str

def entities(doc, scope):
    scope_node = node_by_title(doc, scope)
    if not scope_node:
        return []
    child_nodes = children(doc, scope_node)
    objects_node = _find_node_by_suffix(child_nodes, ": Objects")

    result = []
    if objects_node and objects_node.get('kind') == 'list':
        for line in objects_node.get('lines', []):
            match = re.match(r'^Object (\d+): (.+)', line)
            if match:
                result.append({
                    "id": f"Object {match.group(1)}",
                    "description": match.group(2)
                })
    return result

def recorded_end(doc, scope):
    scope_node = node_by_title(doc, scope)
    if not scope_node:
        return None
    child_nodes = children(doc, scope_node)
    motion_node = _find_node_by_suffix(child_nodes, ": Motion log")
    events_node = _find_node_by_suffix(child_nodes, ": Events")

    max_frame = -1.0
    found = False

    if motion_node and motion_node.get('kind') == 'table':
        for idx, row_dict in table_rows(motion_node):
            try:
                f = float(row_dict.get('frame', ''))
                if f > max_frame:
                    max_frame = f
                found = True
            except (ValueError, TypeError):
                pass

    if events_node and events_node.get('kind') == 'list':
        for line in events_node.get('lines', []):
            match = re.match(r'^Frame (\d+):', line)
            if match:
                f = float(match.group(1))
                if f > max_frame:
                    max_frame = f
                found = True

    return max_frame if found else None

def inputs(doc, scope):
    entities_list = entities(doc, scope)
    entity_ids = {e['id'] for e in entities_list}

    scope_node = node_by_title(doc, scope)
    if not scope_node:
        return []
    child_nodes = children(doc, scope_node)
    events_node = _find_node_by_suffix(child_nodes, ": Events")
    motion_node = _find_node_by_suffix(child_nodes, ": Motion log")

    events = []
    if events_node and events_node.get('kind') == 'list':
        for i, line in enumerate(events_node.get('lines', [])):
            match_init = re.match(r'^Frame (\d+): Object (\d+) \(.*?\) is in view when the video begins\.', line)
            if match_init:
                events.append({'frame': int(match_init.group(1)), 'type': 'initial', 'obj': f"Object {match_init.group(2)}", 'line_idx': i})
                continue
            match_entry = re.match(r'^Frame (\d+): Object (\d+) \(.*?\) enters the scene\.', line)
            if match_entry:
                events.append({'frame': int(match_entry.group(1)), 'type': 'entry', 'obj': f"Object {match_entry.group(2)}", 'line_idx': i})
                continue

    motion_rows = {}
    if motion_node and motion_node.get('kind') == 'table':
        for idx, row_dict in table_rows(motion_node):
            obj_str = row_dict.get('object', '')
            obj_id = _get_object_id_from_string(obj_str)
            if obj_id not in motion_rows:
                motion_rows[obj_id] = []
            motion_rows[obj_id].append((idx, row_dict))

    inputs_list = []
    processed_entities = set()

    def get_state(r_dict):
        return {
            "x": float(r_dict.get('x', 0)),
            "y": float(r_dict.get('y', 0)),
            "vx": float(r_dict.get('vx', 0)),
            "vy": float(r_dict.get('vy', 0))
        }

    for ev in events:
        obj_id = ev['obj']
        if obj_id in entity_ids:
            state_fields = {}
            src_locations = [[events_node['node_id'], ev['line_idx']]]

            if obj_id in motion_rows:
                sorted_rows = sorted(motion_rows[obj_id], key=lambda x: float(x[1].get('frame', '0')))
                target_frame = ev['frame']
                best_row = None
                for r_idx, r_dict in sorted_rows:
                    r_frame = float(r_dict.get('frame', '0'))
                    if r_frame >= target_frame:
                        best_row = (r_idx, r_dict)
                        break
                if best_row is None and sorted_rows:
                    best_row = sorted_rows[0]

                if best_row:
                    r_idx, r_dict = best_row
                    src_locations.append([motion_node['node_id'], r_idx])
                    state_fields = get_state(r_dict)

            inputs_list.append({
                "id": f"input_{obj_id}",
                "time": float(ev['frame']),
                "kind": ev['type'],
                "entities": [obj_id],
                "fields": state_fields,
                "src": src_locations
            })
            processed_entities.add(obj_id)

    for obj_id, rows in motion_rows.items():
        if obj_id not in processed_entities and obj_id in entity_ids:
            sorted_rows = sorted(rows, key=lambda x: float(x[1].get('frame', '0')))
            if sorted_rows:
                first_idx, first_dict = sorted_rows[0]
                frame = float(first_dict.get('frame', 0))
                inputs_list.append({
                    "id": f"input_{obj_id}",
                    "time": frame,
                    "kind": "initial",
                    "entities": [obj_id],
                    "fields": get_state(first_dict),
                    "src": [[motion_node['node_id'], first_idx]]
                })
                processed_entities.add(obj_id)

    return inputs_list

def outcomes(doc, scope):
    scope_node = node_by_title(doc, scope)
    if not scope_node:
        return []
    child_nodes = children(doc, scope_node)
    events_node = _find_node_by_suffix(child_nodes, ": Events")

    outcomes_list = []
    if events_node and events_node.get('kind') == 'list':
        for i, line in enumerate(events_node.get('lines', [])):
            match_col = re.match(r'^Frame (\d+): Object (\d+) \(.*?\) collides with Object (\d+) \(.*?\)\.', line)
            if match_col:
                outcomes_list.append({
                    "time": float(match_col.group(1)),
                    "kind": "collision",
                    "entities": [f"Object {match_col.group(2)}", f"Object {match_col.group(3)}"],
                    "value": None,
                    "src": [[events_node['node_id'], i]]
                })
                continue
            match_exit = re.match(r'^Frame (\d+): Object (\d+) \(.*?\) exits the scene\.', line)
            if match_exit:
                outcomes_list.append({
                    "time": float(match_exit.group(1)),
                    "kind": "exit",
                    "entities": [f"Object {match_exit.group(2)}"],
                    "value": None,
                    "src": [[events_node['node_id'], i]]
                })
                continue
    return outcomes_list

def params(doc, scope):
    return {}


